def number_of_steps(num):
    steps = 0                    # counts every operation performed
    while num > 0:                # keep going until we reach zero
        if num % 2 == 0:
            num //= 2              # even: halve it
        else:
            num -= 1                # odd: knock it down by one
        steps += 1                  # every operation counts as one step
    return steps


if __name__ == "__main__":
    num = 14
    print(number_of_steps(num))

