import java.util.*;

public class Main {
    int numberOfSteps(int num) {
        int steps = 0;                    // counts every operation performed
        while (num > 0) {                  // keep going until we reach zero
            if (num % 2 == 0) {
                num /= 2;                    // even: halve it
            } else {
                num -= 1;                     // odd: knock it down by one
            }
            steps++;                          // every operation counts as one step
        }
        return steps;
    }

    public static void main(String[] args) {
        int num = 14;
        Main solution = new Main();
        System.out.println(solution.numberOfSteps(num));
    }
}

