import java.util.*;

public class Main {
    int numberOfSteps(int num) {
        if (num == 0) {
            return 0;                              // already at zero, no steps needed
        }
        int bitLength = 0;                          // total number of bits in num's binary form
        int popcount = 0;                           // count of 1-bits, each needs one extra subtract step
        int temp = num;
        while (temp > 0) {
            bitLength++;                              // one more bit position seen
            popcount += temp & 1;                      // check if the lowest bit is a 1
            temp >>= 1;                                 // move to the next bit
        }
        return (bitLength - 1) + popcount;            // one divide per bit position minus the last, plus a subtract per 1-bit
    }

    public static void main(String[] args) {
        int num = 14;
        Main solution = new Main();
        System.out.println(solution.numberOfSteps(num));
    }
}

